const cogSource = new ol.source.GeoTIFF({
  normalize: false,
  interpolate: true,
  sources: [
    {
      url: COG_URL,
      nodata: NODATA
    }
  ]
});

const band = ["band", 1];

const validData = [
  "all",
  ["==", band, band], // filters NaN
  [">", band, NODATA_THRESHOLD]
];

const cogLayer = new ol.layer.WebGLTile({
  title: "Air-sea fCO₂ difference",
  source: cogSource,
  opacity: OPACITY,

  style: {
    color: [
      "case",
      validData,

      [
        "interpolate",
        ["linear"],
        band,

        // RdBu_r-style diverging colour scale
        -100, ["color", 5, 48, 97, 0.90],
        -75,  ["color", 33, 102, 172, 0.90],
        -50,  ["color", 67, 147, 195, 0.90],
        -25,  ["color", 146, 197, 222, 0.90],

        0,    ["color", 247, 247, 247, 0.90],

        25,   ["color", 244, 165, 130, 0.90],
        50,   ["color", 214, 96, 77, 0.90],
        75,   ["color", 178, 24, 43, 0.90],
        100,  ["color", 103, 0, 31, 0.90]
      ],

      // Transparent outside valid data
      ["color", 0, 0, 0, 0]
    ]
  }
});

const projection = "EPSG:3857";

const dataExtent = ol.proj.transformExtent(
  [-6, 30, 36, 46],
  "EPSG:4326",
  projection
);

const map = new ol.Map({
  target: "map",

  layers: [
    basemap,
    cogLayer
  ],

  view: new ol.View({
    projection,

    // Center around the middle of the raster
    center: ol.proj.fromLonLat([15, 38]),

    zoom: 4,
    minZoom: 2,
    maxZoom: 12,

    // Optional: constrain navigation to roughly the data region
    extent: dataExtent
  }),

  controls: ol.control.defaults.defaults().extend([
    new ol.control.ScaleLine()
  ])
});

The downloaded input store already has time, lat, lon, and the dfco2 data variable. We open it lazily with xarray, attach the known CRS at dataset level, find every variable that uses the spatial dimensions, and convert the encoded nodata value to NaN before downsampling. That way coarsen(...).mean() ignores nodata pixels for every spatial variable.

source = xr.open_zarr(SOURCE_ZARR)

source = source.rio.set_spatial_dims(x_dim="lon", y_dim="lat").rio.write_crs(CRS)

spatial_data_vars = [
    name
    for name, data_array in source.data_vars.items()
    if any(dim in data_array.dims for dim in ("lat", "lon"))
]

non_numeric_spatial_vars = [
    name
    for name in spatial_data_vars
    if not np.issubdtype(source[name].dtype, np.number)
]


for var_name in spatial_data_vars:
    attrs = source[var_name].attrs.copy()
    source[var_name] = source[var_name].where(source[var_name] != NODATA).astype("float32")
    source[var_name].attrs.update(attrs)
    source[var_name].attrs["grid_mapping"] = "spatial_ref"
    if var_name == NAME:
        source[var_name].attrs["units"] = UNITS



{
    "source": str(SOURCE_ZARR),
    "data_variables": list(source.data_vars),
    "spatial_data_variables": spatial_data_vars,
    "shape": [int(source.sizes["lon"]), int(source.sizes["lat"])],
    "crs": CRS,
    "bounds": [float(value) for value in source.rio.bounds()],
    "resolution": [float(value) for value in source.rio.resolution()],
    "nodata_written": float(NODATA),
}

The native dataset is level 0. Each following level halves the previous level in both spatial dimensions. Using Dataset.coarsen(...).mean() averages all spatial variables together and keeps their coordinate arrays aligned.

if PYRAMID_FACTORS[0] != 1:
    raise ValueError("The first pyramid factor must be 1 for the native-resolution level.")

levels = []
level = source
previous_factor = PYRAMID_FACTORS[0]

for level_index, factor in enumerate(PYRAMID_FACTORS):
    if level_index > 0:
        step = factor / previous_factor
        if not float(step).is_integer():
            raise ValueError(f"Pyramid factor {factor} is not an integer step from {previous_factor}.")

        level = level.coarsen(lon=int(step), lat=int(step), boundary="trim").mean()
        for var_name in spatial_data_vars:
            attrs = source[var_name].attrs.copy()
            level[var_name] = level[var_name].astype("float32")
            level[var_name].attrs.update(attrs)
        level = level.rio.set_spatial_dims(x_dim="lon", y_dim="lat").rio.write_crs(CRS)

    levels.append((factor, level))
    previous_factor = factor

[
    {
        "level": level_index,
        "factor": factor,
        "variables": list(level_ds.data_vars),
        "shape": [int(level_ds.sizes["lon"]), int(level_ds.sizes["lat"])],
        "bounds": [float(value) for value in level_ds.rio.bounds()],
        "resolution": [float(value) for value in level_ds.rio.resolution()],
    }
    for level_index, (factor, level_ds) in enumerate(levels)
]

